var client *Client
if cfg.Enabled {
    client, err := NewClient(cfg)   // новые client и err только внутри if!
    if err != nil {
        return err
    }
    _ = client
}
client.Do()                          // nil — внешний client не изменился

// Правильно:
var err error
if cfg.Enabled {
    client, err = NewClient(cfg)     // = вместо :=
}

type Status int

const (
    StatusNew Status = iota   // 0
    StatusPaid                // 1
    StatusShipped             // 2
)

const (
    _  = iota
    KB = 1 << (10 * iota)     // 1024
    MB                        // 1048576
)
